// 第三方登录核心代码
public String oauthCallback(String code, String state) {
    String cachedState = redis.get("oauth:state:" + state);
    if (cachedState == null) throw new BusinessException("非法请求");
    redis.delete("oauth:state:" + state);
    TokenResponse token = httpPost("https://api.weixin.qq.com/sns/oauth2/access_token", code);
    UserInfo userInfo = httpGet("https://api.weixin.qq.com/sns/userinfo", token.getAccessToken());
    User user = userService.findByOpenid(userInfo.getOpenid());
    if (user == null) user = userService.register(userInfo);
    return jwtService.generate(user.getId());
}

// 扫码登录核心代码
public String scanLogin(String sceneId, String code) {
    String cachedCode = redis.get("scan:code:" + sceneId);
    if (cachedCode == null || !cachedCode.equals(code)) throw new BusinessException("非法请求");
    redis.delete("scan:code:" + sceneId);
    User user = userService.findBySceneId(sceneId);
    if (user == null) user = userService.register(sceneId);
    webSocketService.push(sceneId, "login_success");
    return jwtService.generate(user.getId());
}
